&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Outreach/Salesloft/Amplemarket&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Gong&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Demandbase&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;LinkedIn Sales Navigator&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(0, 0, 0) !important; font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;ZoomInfo or similar.&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
