&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Observability tools (Datadog, Grafana)&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
