&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(34, 34, 34); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;CI/CD &amp;amp; Automation: Jenkins, CircleCI, GitHub Actions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(34, 34, 34); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Data &amp;amp; Testing:ELT pipelines, test automation utilities, whitebox testing strategies&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;color: rgb(34, 34, 34); font-size: 10pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Databases: SQL and NoSQL databases (e.g., Postgres, SAP , Oracle, DB2 ertc)&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
