&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;emphasis&quot; style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Hands-on experience working with any cloud technologies(AWS, GCP, Azure) and containerization methodologies like Docker, K8s&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span class=&quot;emphasis&quot; style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience interacting with continuous integration tools like BuildKite&lt;/span&gt;&lt;/li&gt;
