&lt;li style=&quot;color: rgb(34, 34, 34) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(34, 34, 34); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;SQL, BigQuery&lt;/span&gt;&lt;/li&gt;
