&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Databases: Postgres and all the major Databases&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Languages: Go, Java&lt;/span&gt;&lt;/li&gt;
